        private async Task LoadIcons(DataGridView grid,IEnumerable<int> requested)
        {
            var ids=requested.Distinct().Where(id=>!icons.ContainsKey(id)).ToArray();var found=new ConcurrentDictionary<int,Bitmap>();
            await Task.Run(()=>Parallel.ForEach(ids,new ParallelOptions {MaxDegreeOfParallelism=5},id=>{try{byte[] b=api.Icon(id);if(b!=null)using(var s=new MemoryStream(b))using(var im=Image.FromStream(s))found[id]=new Bitmap(im);}catch{}}));
            if(IsDisposed){foreach(var b in found.Values)b.Dispose();return;}foreach(var p in found){if(icons.ContainsKey(p.Key))p.Value.Dispose();else icons[p.Key]=p.Value;}
            if(grid.IsDisposed)return;foreach(DataGridViewRow row in grid.Rows){int id=Convert.ToInt32(row.Cells["id"].Value);Bitmap b;if(icons.TryGetValue(id,out b))row.Cells["icon"].Value=b;}
        }
